const fail = (ms, text) => new Promise((resolve, reject) => setTimeout(reject, ms, new Error(text)));

function firstOk(list) {
  return new Promise((resolve, reject) => {
    const errors = [];
    let failed = 0;
    if (list.length === 0) reject(new AggregateError(errors, "empty"));
    list.forEach((item, i) => {
      Promise.resolve(item).then(resolve, (error) => {
        errors[i] = error.message;
        failed += 1;
        if (failed === list.length) reject(new AggregateError(errors, "all failed"));
      });
    });
  });
}

firstOk([]).catch((error) => console.log(error.name + " " + error.errors.length));
firstOk([fail(40, "x"), "cached"]).then((value) => console.log(value));
firstOk([fail(40, "late"), fail(10, "early")]).catch((error) => console.log(error.errors.join(",")));
